import {RelayAPI} from './api.mjs?v=dm-20261002';
import {API_BASE} from './config.mjs?v=dm-20261002';
const $=s=>document.querySelector(s), h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={room:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-8h6v8',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tasks:'M8 5h13M8 12h13M8 19h13 M3 5h.1M3 12h.1M3 19h.1',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',messages:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5',memory:'M4 3h6a3 3 0 0 1 3 3v16a4 4 0 0 0-4-3H4z M20 3h-4a3 3 0 0 0-3 3 M13 22a4 4 0 0 1 4-3h3V3',builds:'M12 3l9 5v9l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v9',needs:'M12 8v5 M12 17h.01 M10.3 3.9l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0',connect:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.tasks}"/></svg>`;
const initials=name=>name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
let state=emptyState(), store=null,mode='offline',view=location.hash.slice(1)||'overview',channel='general',taskLayout='board',taskFilter='',taskSearch='',lastSync=null,refreshing=false,toastTimer;
let actor={id:'owner',owner:true},currentUser=null,workspaceManager=null,backendCapabilities={},currentRoom=null,workers=[],authRole='manager',authPage='login',authStatus=null,authError='',authBusy=false,recoverySecret='';
const api=new RelayAPI({base:API_BASE});
const updatesTransport=new RelayAPI({base:API_BASE?API_BASE.replace(/\/relay$/,'/relay-updates'):'',storage:null});
const updates=createUpdates({api:{get token(){return api.token;},call(action,data){updatesTransport.token=api.token;return updatesTransport.call(action,data);}},getUser:()=>currentUser,isLive:()=>mode==='live',toast,onSessionError:()=>clearSession()});
const hardwareUI=createHardware({api,getUser:()=>currentUser,isLive:()=>mode==='live',onSessionError:()=>clearSession()});
const dm=createInbox({api,getUser:()=>currentUser,isLive:()=>mode==='live',toast,onSessionError:()=>clearSession()});
const demoUser=()=>currentUser||{id:'owner',name:'Example manager',role:'manager'};
const demoDM=createInbox({api:createDemoInboxAPI(demoUser,()=>state.agents),getUser:demoUser,isLive:()=>mode==='demo',toast,onSessionError:()=>{}});
const roomDrafts=new Map();
const isManager=()=>mode==='demo'&&!currentUser||currentUser?.role==='manager';
const taskControlsReady=()=>mode==='demo'||backendCapabilities.taskControlsV1===true;
const canCreateTask=()=>taskControlsReady()&&(isManager()||currentUser?.workRole==='Coordinator');
const messageDrafts=new Map();
const names={room:'My room',overview:'Overview',tasks:'Task board',team:'Agents',messages:'Team messages',inbox:'Private inbox',memory:'Project memory',updates:'Update room',builds:'Builds',needs:'Questions',connect:'Account',software:'Software',hardware:'Hardware'};
const sidebarNavigation=createSidebar({names,icon,escape:h});
const agent=id=>state.agents.find(a=>a.id===id);
const name=id=>id==='owner'?(isManager()?(currentUser?.name||'You'):'Manager'):agent(id)?.name||'Unassigned';
const taskNames=t=>taskAssignees(t).map(a=>name(a.agentId)).join(', ')||'Unassigned';
const taskAvatars=t=>`<span class="task-avatars">${taskAssignees(t).slice(0,3).map(a=>avatar(a.agentId)).join('')}${taskAssignees(t).length>3?`<span class="avatar">+${taskAssignees(t).length-3}</span>`:''}</span>`;
const avatar=id=>`<span class="avatar">${h(initials(name(id)))}</span>`;
const relative=v=>{if(!v)return 'No check-in yet';const n=Math.max(0,Date.now()-new Date(v).getTime());return n<60000?'Just now':n<3600000?Math.floor(n/60000)+'m ago':n<86400000?Math.floor(n/3600000)+'h ago':Math.floor(n/86400000)+'d ago';};
const badge=status=>`<span class="badge ${h(status)}">${h(LABEL[status]||status)}</span>`;
const button=(label,action,id='',style='')=>`<button type="button" class="button ${style}" data-action="${action}" data-id="${h(id)}">${h(label)}</button>`;
const empty=(title,body,action='',label='')=>`<div class="empty">${icon('tasks')}<h3>${h(title)}</h3><p>${h(body)}</p>${action?button(label,action,'','small'):''}</div>`;
const field=(label,key,value='',type='text',hint='')=>`<label class="field"><span class="field-label">${h(label)}</span>${type==='textarea'?`<textarea name="${key}" aria-label="${h(label)}" maxlength="12000">${h(value)}</textarea>`:`<input name="${key}" aria-label="${h(label)}" type="${type}" value="${h(value)}" ${type==='password'?'autocomplete="off" spellcheck="false"':'autocomplete="off"'} maxlength="${key==='token'?500:2000}">`}${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,key,options,value='')=>`<label class="field"><span class="field-label">${h(label)}</span><select name="${key}" aria-label="${h(label)}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></label>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function title(heading,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">CODERCODE / STUDIO</div><h1>${h(heading)}</h1><p class="subtitle">${h(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function openDialog(){
  const modal=$('#modal'),heading=$('#modal-content .modal-header h2'),description=$('#modal-content .modal-header p');
  if(heading){heading.id='dialog-heading';modal.setAttribute('aria-labelledby',heading.id);}
  if(description?.textContent.trim()){description.id='dialog-description';modal.setAttribute('aria-describedby',description.id);}
  else modal.removeAttribute('aria-describedby');
  if(!modal.open)modal.showModal();
  else if(!$('#modal-content').contains(document.activeElement))$('#modal-content').querySelector('button,input,select,textarea')?.focus();
}
function syncNavigation({returnFocus=false}={}){
  const sidebar=$('.sidebar'),toggle=$('#menu-toggle'),compact=getComputedStyle(toggle).display!=='none';
  if(!compact)sidebar.classList.remove('open');
  const open=compact&&sidebar.classList.contains('open');
  sidebar.id='workspace-sidebar';toggle.setAttribute('aria-controls',sidebar.id);toggle.setAttribute('aria-expanded',String(open));
  if(compact&&!open&&(returnFocus||sidebar.contains(document.activeElement)))toggle.focus();
  sidebar.inert=compact&&!open;
  if(sidebar.inert)sidebar.setAttribute('aria-hidden','true');else sidebar.removeAttribute('aria-hidden');
}
function formDialog(heading,sub,body,submitLabel,onSubmit){$('#modal-content').innerHTML=`<div class="modal-header"><div><h2>${h(heading)}</h2><p>${h(sub)}</p></div><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div><form id="dialog-form">${body}<div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancel','close') }<button class="button primary" type="submit">${h(submitLabel)}</button></div></form>`;$('#dialog-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(f.dataset.saving==='true')return;const data=Object.fromEntries(new FormData(f));data.dependencies=Array.from(f.querySelectorAll('[name="dependencies"]:checked')).map(x=>x.value);data.agentIds=Array.from(f.querySelectorAll('[name="agentIds"]:checked')).map(x=>x.value);const submit=f.querySelector('[type="submit"]');f.dataset.saving='true';submit.disabled=true;f.querySelector('.form-error').textContent='';try{const keep=await onSubmit(data,f);if(!keep&&$('#dialog-form')===f)$('#modal').close();}catch(err){f.querySelector('.form-error').textContent=err.message;}finally{f.dataset.saving='false';submit.disabled=false;}};openDialog();}
function showText(heading,text){$('#modal-content').innerHTML=`<div class="modal-header"><div><h2>${h(heading)}</h2><p>Copy this into the agent’s next chat. It contains no access token.</p></div><button class="icon-button" data-action="close" aria-label="Close">×</button></div><textarea class="handoff-text" readonly id="handoff-text" aria-label="Message to copy">${h(text)}</textarea><div class="modal-footer">${button('Close','close')}${button('Copy message','copy-text','','primary')}</div>`;openDialog();}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard');}catch{showText('Copy message',text);$('#handoff-text').select();}}
function useContext(snapshot){workspaceManager=snapshot.manager||null;backendCapabilities=snapshot.capabilities||{};if(!snapshot)return;state=snapshot.state||state;currentUser=snapshot.user||currentUser;actor=snapshot.actor||actor;currentRoom=snapshot.room||currentRoom;workers=snapshot.workers||[];}
async function mutate(type,payload){if(type.startsWith('task.')&&!taskControlsReady())throw new Error('Task controls are waiting for the matching backend update.');if(mode==='offline'){formConnection();throw new Error('Sign in to save shared work.');}const op={id:newId(),type,payload};if(mode==='demo')state=applyOperation(state,op,actor);else{const result=await store.mutate(op);state=result?.state||result;useContext(store.snapshot);}lastSync=new Date().toISOString();render();return op.id;}
async function loadContext(){const token=api.token,snapshot=await api.context();if(!token||token!==api.token)return false;useContext(snapshot);lastSync=new Date().toISOString();return true;}
function deferBackgroundRender(){return view==='updates'||$('#modal').open||document.activeElement?.matches('input,textarea,select,button:focus-visible,a:focus-visible');}
async function refresh(silent=false){if(!store||mode!=='live'||refreshing)return;const refreshToken=api.token;refreshing=true;try{if(!await loadContext())return;if(silent&&deferBackgroundRender())return;render();if(!silent)toast('Workspace is up to date');}catch(e){if(refreshToken!==api.token&&api.token)return;if(e.status===401||['SESSION','UNAUTHORIZED','STALE_SESSION','DELETED'].includes(e.code)){clearSession();toast('Your session ended. Please sign in again.');}else{$('#connection-text').textContent='Connection needs attention';$('#connection-dot').classList.remove('connected');if(!silent)toast(e.message);}}finally{refreshing=false;}}
function clearSession(){hardwareUI.reset();updates.reset();dm.reset();demoDM.reset();recoverySecret='';api.disconnect();store=null;currentUser=null;workspaceManager=null;backendCapabilities={};currentRoom=null;workers=[];state=emptyState();actor={id:'owner',owner:true};mode='offline';messageDrafts.clear();roomDrafts.clear();render();}
async function accountCall(action,payload){const result=await api.call(action,payload);await loadContext();render();return result;}
function welcome(){return `<section class="welcome"><div class="welcome-copy"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>A shared home for your agents.</h2><p>Keep game development moving across chats. Assign the work, keep the decisions and give every returning agent a clear place to begin.</p><div class="actions">${button('Connect project','connect','','primary')}${button('Explore example board','demo')}</div></div><div class="welcome-steps"><div class="welcome-step"><span class="step-number">1</span><div><strong>Connect your private board</strong><p>Project data stays separate from this public website.</p></div></div><div class="welcome-step"><span class="step-number">2</span><div><strong>Name your team</strong><p>Give each chat a role and a fresh session.</p></div></div><div class="welcome-step"><span class="step-number">3</span><div><strong>Build, review, keep going</strong><p>Save checkpoints and resume from any connected chat.</p></div></div></div></section>`;}
function taskRow(t){return `<button class="task-link task-row" data-action="task" data-id="${h(t.id)}"><span class="task-indicator ${h(t.status)}"></span><div class="task-main"><div class="task-name">${h(t.title)}</div><div class="task-meta"><span class="priority ${h(t.priority)}"></span><span>${h(t.priority)} priority</span><span>·</span><span>${h(taskNames(t))}</span><span>·</span><span>${h(relative(t.updatedAt))}</span></div></div><div class="task-right">${badge(t.status)}${taskAvatars(t)}</div></button>`;}
function overview(){const pending=state.requests.filter(r=>r.status==='open');const working=activeTasks(state).filter(t=>t.status==='working');const review=activeTasks(state).filter(t=>t.status==='review');const done=activeTasks(state).filter(t=>t.status==='done');const active=state.agents.filter(a=>a.enabled&&a.session);const activity=state.activity.slice(0,5);const latest=state.builds.at(-1);return title('Your studio, in sync.',state.project.goal||'A clear view of the work, the team and what comes next.',isManager()?button('Project direction','project'):'')+(mode==='offline'?welcome():'')+`<div class="stats">${[['Tasks in progress',working.length,'Owned work across the team','tasks'],['Ready for review',review.length,'Waiting for another pair of eyes','tasks'],[isManager()?'Needs your input':'Needs the manager',pending.length,'Questions that unblock the team','needs'],['Completed',done.length,'Reviewed and accepted tasks','builds']].map(([l,n,f,i],idx)=>`<div class="stat ${idx===2&&n?'alert':''}"><div class="stat-top">${h(l)}${icon(i)}</div><div class="stat-num">${n.toString().padStart(2,'0')}</div><div class="stat-foot">${h(f)}</div></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-header"><h2>Work in motion</h2><a class="text-button" href="#tasks">View task board</a></div>${activeTasks(state).filter(t=>t.status!=='done').slice(0,5).map(taskRow).join('')||empty('Make room for your first milestone','Give an agent one clear task and a definition of done.',canCreateTask()?'new-task':'','Create a task')}</section><section class="panel"><div class="panel-header"><h2>${isManager()?'Needs you':'Needs the manager'}</h2><span class="badge">${pending.length} open</span></div>${pending.slice(0,3).map(r=>`<div class="needs-card"><h3>${h(r.title)}</h3><p>${h(r.body)}</p>${isManager()?`<button class="text-button" data-action="resolve" data-id="${h(r.id)}">Answer ${h(name(r.from))}</button>`:''}</div>`).join('')||empty('Nothing blocking the team','Questions and decisions will appear here.')}</section><section class="panel"><div class="panel-header"><h2>Latest playable build</h2><a class="text-button" href="#builds">All builds</a></div>${latest?`<div class="panel-body"><h3>${h(latest.title)}</h3><p class="subtitle section-space">${h(latest.notes)}</p><div class="spacer"></div><a class="button small" href="${h(safeLink(latest.url))}" target="_blank" rel="noopener noreferrer">Open build</a></div>`:empty('Your next playtest starts here','Add a build link with its tested version and known issues.','new-build','Add build')}</section></div><div><section class="panel"><div class="panel-header"><h2>Your agents</h2><span class="badge">${active.length} sessions</span></div><div class="panel-body">${state.agents.slice(0,5).map(a=>`<div class="mini-agent">${avatar(a.id)}<div class="mini-agent-info"><strong>${h(a.name)}</strong><small>${h(a.role)} · ${h(a.enabled?relative(a.lastSeen):'Paused')}</small></div>${isManager()||a.id===actor.id?`<button class="text-button" data-action="handoff" data-id="${h(a.id)}">Handoff</button>`:''}</div>`).join('')||`<div class="quick-brief"><h3>Build your team</h3><p>Add named roles for your chats. Start each session with a focused brief.</p>${isManager()?button('＋ Add worker','new-agent','','small'):''}</div>`}</div></section><section class="panel"><div class="panel-header"><h2>Recent activity</h2></div><div class="panel-body">${activity.map(x=>`<div class="activity-item"><span class="activity-node"></span><div><p>${h(x.title)}</p><time>${h(relative(x.createdAt))}</time></div></div>`).join('')||'<p class="subtitle">Saved changes will appear here.</p>'}</div></section><div class="quick-brief section-space"><div class="eyebrow">KEEP THE CONTEXT</div><h3>A fresh session. The same mission.</h3><p>Copy an agent’s handoff to continue with its task, saved progress and project rules.</p><a class="text-button" href="#team">${isManager()?'Manage your team':'Meet the team'}</a></div></div></div>`;}
function tasks(){const rows=activeTasks(state).filter(t=>(!taskFilter||assignedTo(t,taskFilter)||taskFilter==='unassigned'&&!taskAssignees(t).length)&&(`${t.title} ${t.description}`.toLowerCase().includes(taskSearch.toLowerCase())));return title('Task board',taskControlsReady()?'Clear ownership. Small milestones. A playable game.':'Task controls are waiting for the matching backend update.',(canCreateTask()?button('New task','new-task','','primary'):'')+(isManager()&&taskControlsReady()?button('Deleted tasks','deleted-tasks'):'') )+`<div class="toolbar"><input class="search" id="task-search" placeholder="Search tasks…" aria-label="Search tasks" value="${h(taskSearch)}"><select id="task-filter" aria-label="Filter by agent"><option value="">All agents</option><option value="unassigned" ${taskFilter==='unassigned'?'selected':''}>Unassigned</option>${state.agents.map(a=>`<option value="${h(a.id)}" ${taskFilter===a.id?'selected':''}>${h(a.name)}</option>`).join('')}</select><div class="view-tabs"><button data-action="layout" data-id="board" class="${taskLayout==='board'?'selected':''}">Board</button><button data-action="layout" data-id="list" class="${taskLayout==='list'?'selected':''}">List</button></div></div>${taskLayout==='board'?`<div class="kanban">${STATUS.map(status=>`<section class="kanban-col"><div class="kanban-heading"><span>${LABEL[status]}</span><span class="count">${rows.filter(t=>t.status===status).length}</span></div>${rows.filter(t=>t.status===status).map(t=>`<button class="task-card" data-action="task" data-id="${h(t.id)}"><span class="badge">${h(t.priority)} priority</span><div class="task-name">${h(t.title)}</div>${t.dependencies.length?`<div class="task-meta">${t.dependencies.length} prerequisite${t.dependencies.length===1?'':'s'}</div>`:''}<div class="card-footer"><span>${h(taskNames(t))}</span>${taskAssignees(t).length?taskAvatars(t):'<span>＋</span>'}</div></button>`).join('')}</section>`).join('')}</div>`:`<section class="panel">${rows.map(taskRow).join('')||empty('No matching tasks','Try a different search or create a task.')}</section>`}`;}
function team(){return title('Your team','Every worker has a name, a room and a clear place in the project.',isManager()?button('Add worker','new-agent','','primary'):'')+(state.agents.length?`<div class="agent-grid">${state.agents.map(a=>`<section class="panel agent-card"><div class="agent-card-header">${avatar(a.id)}<div><h3>${h(a.name)}</h3><div class="role">${h(a.role)}</div></div></div><span class="model">${h(a.model||'Model not specified')}</span><div class="checkpoint">${h(a.checkpoint||'A saved checkpoint will appear here after this worker reports progress.')}</div><div class="times">Last contact: ${h(relative(a.lastSeen))}<br>Saved progress: ${h(a.lastProgress?relative(a.lastProgress):'None yet')}<br>${a.enabled?'Enabled':'Paused'} · ${a.session?'Session started':'Awaiting sign-in'}</div><div class="actions">${isManager()||a.id===actor.id?button('Copy handoff','handoff',a.id,'small'):''}${mode==='demo'?button(a.session?'Replace session':'Start session','session',a.id,'small'):''}${isManager()&&mode==='live'&&workers.find(w=>w.agentId===a.id)?button('Manage worker','worker-edit',workers.find(w=>w.agentId===a.id).id,'small'):''}</div></section>`).join('')}</div>`:`<section class="panel">${empty('A room for everyone','The manager can create named worker accounts for your chats.',isManager()?'new-agent':'','Add your first worker')}</section>`);}
function messageMarkup(m){return `<article class="message">${avatar(m.from)}<div class="message-body"><strong>${h(name(m.from))}</strong><time>${h(relative(m.createdAt))}</time>${m.to?`<div class="message-to">To ${h(name(m.to))}</div>`:''}<p>${h(m.body)}</p></div></article>`;}
function messages(){const rows=state.messages.filter(m=>channel==='general'?!m.to&&!m.taskId:channel==='owner'?m.to==='owner':m.to===channel||m.from===channel);return title('Messages','A shared conversation that survives the next restart.')+`<section class="panel messages-layout"><aside class="channels"><div class="nav-label">CHANNELS</div>${[['general','# General'],['owner',isManager()?'To you':'To manager'],...state.agents.map(a=>[a.id,a.name])].map(([id,l])=>`<button class="channel-button ${channel===id?'active':''}" data-action="channel" data-id="${h(id)}">${h(l)}</button>`).join('')}</aside><div class="messages-panel">${rows.length?rows.slice(-60).map(messageMarkup).join(''):empty('Start a conversation','Messages here stay with the project.')}<form id="compose" class="compose"><label class="field"><span class="field-label">Post as ${h(currentUser?.name||'CoderCode')}</span><textarea name="body" aria-label="Post as ${h(currentUser?.name||'CoderCode')}" required maxlength="12000" placeholder="Share an update, ask a question or leave a decision…">${h(messageDrafts.get(channel)||'')}</textarea></label><div class="form-error" role="alert"></div><div class="actions"><span class="checkbox-caption">${channel==='general'?'Visible to the project team':'Shared project record — not a private message'}</span><button type="submit" class="button primary small">Post message</button></div></form></div></section>`;}
function memory(){return title('Project memory','The decisions every agent should carry forward.',isManager()?button('Add note','new-note','','primary'):'')+`<section class="panel"><div class="panel-header"><h2>Project direction</h2>${isManager()?'<button class="text-button" data-action="project">Edit direction</button>':''}</div><div class="panel-body"><p class="subtitle pre-wrap">${h(state.project.goal||'Set the next game milestone.')}</p><div class="spacer"></div><p class="subtitle pre-wrap">${h(state.project.rules)}</p>${state.project.gameRepo?`<div class="spacer"></div><a class="text-button" href="${h(safeLink(state.project.gameRepo))}" target="_blank" rel="noopener noreferrer">Open game repository</a>`:''}</div></section><div class="note-grid section-space">${state.memory.map(n=>`<section class="panel note-card"><h3>${h(n.title)}</h3><p>${h(n.body)}</p><div class="card-footer"><span>Updated ${h(relative(n.updatedAt))}</span>${isManager()?`<button class="text-button" data-action="edit-note" data-id="${h(n.id)}">Edit note</button>`:''}</div></section>`).join('')}</div>`;}
function builds(){return title('Playable builds','Keep the exact version, evidence and known issues together.',button('Add build','new-build','','primary'))+(state.builds.length?state.builds.slice().reverse().map(b=>`<section class="panel build-card"><div class="build-icon">${icon('builds')}</div><div class="build-main"><h3>${h(b.title)}</h3><small>${h(relative(b.createdAt))} · Added by ${h(name(b.from))}${b.commit?' · '+h(b.commit):''}</small><p>${h(b.notes)}</p><div class="callout">Validation: ${h(b.tests)}</div></div><a class="button small" href="${h(safeLink(b.url))}" target="_blank" rel="noopener noreferrer">Open build</a></section>`).join(''):`<section class="panel">${empty('No build links yet','Add a playable URL or release download after testing.','new-build','Add a build')}</section>`);}
function needs(){return title(isManager()?'Needs you':'Questions for the manager',isManager()?'Answer a question and let the team keep moving.':'Ask for a decision and keep the team informed.',button('Add question','new-request'))+(state.requests.length?state.requests.slice().reverse().map(r=>`<section class="panel"><div class="panel-header"><h2>${h(r.title)}</h2><span class="badge ${r.status==='open'?'blocked':'done'}">${r.status==='open'?'Open':'Answered'}</span></div><div class="panel-body"><p class="subtitle pre-wrap">${h(r.body)}</p><div class="spacer"></div><small class="muted">From ${h(name(r.from))} · ${h(relative(r.createdAt))}</small>${r.answer?`<div class="request-answer">${h(r.answer)}</div>`:`<div class="spacer"></div>${isManager()?button('Answer question','resolve',r.id,'primary small'):'<p class="subtitle">Waiting for the manager.</p>'}`}</div></section>`).join(''):`<section class="panel">${empty('No unanswered questions','Agents can ask for decisions here without losing their task.')}</section>`);}
function safeLink(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function connections(){if(mode==='demo')return title('Example account','This is a sample workspace. No login or account changes are saved.')+`<section class="panel"><div class="panel-body"><p class="instruction">Real accounts need the private login service. Return to sign-in to see whether it has been activated.</p>${button('Return to sign in','connect','','primary')}</div></section>`;return title(isManager()?'Studio settings':'Your account',isManager()?'Manage your login and the workers you invite.':`Signed in as ${currentUser.name}. Your manager controls this worker slot.`)+`<div class="settings-grid"><section class="panel"><div class="panel-header"><h2>Your login</h2><span class="badge done">${isManager()?'Manager':'Worker'}</span></div><div class="panel-body"><div class="identity-card"><span class="avatar">${h(initials(currentUser.name))}</span><div><strong>${h(currentUser.name)}</strong><p class="subtitle">@${h(currentUser.username)}</p></div></div><p class="instruction">${isManager()?'Only your manager account can create workers, reset passwords and delete the studio.':'You can work with the team and save notes in your own room. Ask your manager if you need a password reset.'}</p><div class="actions">${isManager()?button('Change my password','password-change'):''}${button('Sign out','logout')}</div></div></section><section class="panel"><div class="panel-header"><h2>Connect your chats</h2></div><div class="panel-body instruction"><ol><li>The manager creates a worker name, username and password.</li><li>Give that worker its login details privately.</li><li>It chooses <strong>Worker</strong> on the login page and signs in.</li><li>It lands in its own room, with its assignments, notes and next steps.</li></ol><a href="AGENT-GUIDE.md" target="_blank" rel="noopener">Agent connection guide</a><p>Chats need browser or API tools to access the workspace directly. A chat without tools can exchange handoffs through you.</p></div></section>${isManager()?`<section class="panel wide"><div class="panel-header"><h2>Worker slots</h2>${button('Add worker','new-agent','','primary small')}</div><div class="panel-body">${workers.length?workers.map(w=>`<div class="worker-row"><span class="avatar">${h(initials(w.name))}</span><div class="worker-row-info"><strong>${h(w.name)}</strong><small>@${h(w.username)} · ${h(w.workRole||'Worker')} · ${w.enabled?'Enabled':'Disabled'}</small></div><div class="actions">${button('Open room','worker-room',w.id,'small')}${button('Manage','worker-edit',w.id,'small')}</div></div>`).join(''):empty('Your first worker is next','Give each chat its own name and password.','new-agent','Add worker')}</div></section><section class="panel"><div class="panel-header"><h2>Update approvals</h2></div><div class="panel-body"><p class="instruction">Choose one sign-off, your approval only, or two agent sign-offs. You can allow agents to approve their own updates. The Update room also gives you a direct manager approval button.</p>${button('Manage update approvals','update-policy')}</div></section><section class="panel"><div class="panel-header"><h2>Account recovery</h2></div><div class="panel-body"><p class="instruction">Your recovery code lets you reset your manager password from the login screen. Keep it somewhere private. Generating a new code replaces the old one.</p>${button('Replace recovery code','recovery-rotate')}</div></section><section class="panel danger-zone"><div class="panel-header"><h2>Delete studio</h2><span class="badge blocked">Manager only</span></div><div class="panel-body"><p class="instruction">Permanently delete the app’s accounts, worker rooms, tasks, messages and project data. This does not remove the public website files or copies in provider backups.</p>${button('Delete entire studio','workspace-delete','','danger')}</div></section>`:''}</div>`;}
function room(){const ownTasks=activeTasks(state).filter(t=>assignedTo(t,actor.id)&&t.status!=='done');const a=agent(actor.id);const notes=roomDrafts.get(currentUser?.id)?.body??currentRoom?.body??'';return title(`Welcome, ${currentUser?.name||'CoderCode'}.`,isManager()?'Your manager room. Give your team a direction and keep the project moving.':'This is your room. Pick up your assignments, save your next step and work with the team.',isManager()?button('Add worker','new-agent','','primary'):button('Copy my handoff','handoff',actor.id))+`<div class="room-banner"><span class="avatar room-avatar">${h(initials(currentUser?.name||'CoderCode'))}</span><div><span class="eyebrow">YOUR SPACE IN RELAY</span><h2>${h(currentUser?.name||'CoderCode')}’s room</h2><p>${isManager()?'Studio manager':h(currentUser?.workRole||'Worker')} · @${h(currentUser?.username||'codercode')}</p></div><span class="badge done">${mode==='demo'?'Example worker':'Signed in'}</span></div><div class="room-grid"><div><section class="panel"><div class="panel-header"><h2>${isManager()?'Team overview':'Your assignments'}</h2><a class="text-button" href="#tasks">Open task board</a></div>${(isManager()?activeTasks(state).filter(t=>t.status!=='done').slice(0,5):ownTasks).map(taskRow).join('')||empty(isManager()?'Ready for the first milestone':'Your next assignment is waiting',isManager()?'Create a task and assign it to a worker.':'Claim an available task from the board, or ask your manager what to do next.',isManager()?'new-task':'','Create a task')}</section>${!isManager()?`<section class="panel"><div class="panel-header"><h2>Restart checkpoint</h2>${button('Update checkpoint','checkpoint','','small')}</div><div class="panel-body"><p class="subtitle pre-wrap">${h(a?.checkpoint||'Save the next step before leaving. Your replacement session can pick up here.')}</p><div class="spacer"></div><small class="muted">${h(a?.lastProgress?relative(a.lastProgress):'No checkpoint saved yet')}</small></div></section>`:`<section class="panel"><div class="panel-header"><h2>Your team</h2><a href="#connect" class="text-button">Manage workers</a></div><div class="panel-body">${workers.slice(0,5).map(w=>`<div class="mini-agent"><span class="avatar">${h(initials(w.name))}</span><div class="mini-agent-info"><strong>${h(w.name)}</strong><small>${h(w.workRole||'Worker')} · ${w.enabled?'Enabled':'Disabled'}</small></div>${button('Room','worker-room',w.id,'small')}</div>`).join('')||'<p class="subtitle">Add a worker to give your first chat a name and its own room.</p>'}</div></section>`}</div><section class="panel room-notes"><div class="panel-header"><h2>Your room notes</h2><span class="badge">${isManager()?'Only you':'You + manager'}</span></div><div class="panel-body"><p class="instruction no-margin">Keep working notes and a plan for your next visit. ${isManager()?'These notes belong to your manager account.':'Other workers cannot read this room. Your manager can.'}</p><form id="room-form"><label class="field section-space"><span class="field-label">Private working notes</span><textarea name="body" id="room-body" aria-label="Private working notes" maxlength="24000" placeholder="What I’m working on, what I learned, what comes next…">${h(notes)}</textarea></label><div class="form-error" role="alert"></div><div class="room-save"><small id="room-save-state">${roomDrafts.has(currentUser?.id)?'Unsaved changes':mode==='demo'?'Example notes — not saved':currentRoom?.updatedAt?'Saved '+h(relative(currentRoom.updatedAt)):'Not saved yet'}</small><button class="button primary small" type="submit">Save room notes</button></div></form></div></section></div>`;}
function software(){return title('Software','A place for your studio’s software.')+`<section class="panel">${empty('Software will go here','This section is ready to organize later. No software tools are connected here yet.')}</section>`;}
function hardware(){return title('Hardware','Shared calculations for your agents.')+hardwareUI.render();}
function render(){const signedIn=mode==='live'||mode==='demo';$('.skip').setAttribute('href',signedIn?'#content':'#auth-form');$('.shell').hidden=!signedIn;$('#auth-screen').hidden=signedIn;if(!signedIn){renderAuth();return;}if(!names[view]||view==='room'&&mode==='demo'&&!currentUser)view=mode==='live'?'room':'overview';$('#nav').innerHTML=sidebarNavigation.render({view,hasRoom:!!currentUser,openQuestions:state.requests.filter(r=>r.status==='open').length});renderWorkspaceBrand(document,currentUser,mode,workspaceManager);$('#breadcrumb').textContent=names[view];$('#sync-time').textContent=mode==='live'?'Synced '+relative(lastSync):'Example project';$('#connection-text').textContent=mode==='live'?'Signed in · '+(isManager()?'Manager':'Worker'):'Example board · not saved';$('#connection-dot').classList.toggle('connected',mode==='live');$('#identity-name').textContent=currentUser?.name||'Example manager';$('#identity-role').textContent=isManager()?'Studio manager':'Worker';$('#identity-avatar').textContent=initials(currentUser?.name||'Example manager');$('#account-button').textContent=mode==='live'?'Sign out':'Return to sign in';$('#account-button').dataset.action=mode==='live'?'logout':'connect';$('#top-new-task').hidden=!canCreateTask();$('#mode-banner').innerHTML=mode==='demo'?`<div class="banner"><span>EXAMPLE BOARD · Sample activity. Changes here are not saved.</span><div class="actions">${button(currentUser?'Preview manager board':'Preview worker room',currentUser?'demo':'demo-worker','','text-button')}<button class="text-button" data-action="connect">Return to sign in</button></div></div>`:'';$('#content').innerHTML=({room,overview,tasks,team,messages,inbox:()=>mode==='demo'?demoDM.render():dm.render(),updates:()=>updates.render(),memory,builds,needs,software,hardware,connect:connections})[view]();document.title=`${names[view]} · Relay`;syncNavigation();(mode==='demo'?demoDM:dm).mount();updates.mount();hardwareUI.mount();if($('#compose')){$('#compose').elements.body.oninput=e=>messageDrafts.set(channel,e.target.value);$('#compose').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{const sentChannel=channel;await mutate('message.add',{body:f.elements.body.value,to:channel==='general'?null:channel});messageDrafts.delete(sentChannel);render();toast('Message saved');}catch(err){f.querySelector('.form-error').textContent=err.message;b.disabled=false;}};}if($('#task-search'))$('#task-search').oninput=e=>{taskSearch=e.target.value;const start=e.target.selectionStart;render();$('#task-search').focus();$('#task-search').setSelectionRange(start,start);};if($('#task-filter'))$('#task-filter').onchange=e=>{taskFilter=e.target.value;render();};if($('#room-form')){$('#room-body').oninput=e=>{const old=roomDrafts.get(currentUser.id);roomDrafts.set(currentUser.id,{body:e.target.value,version:old?.version??currentRoom?.version??0});$('#room-save-state').textContent='Unsaved changes';};$('#room-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{const draft=roomDrafts.get(currentUser.id);if(mode==='demo'){currentRoom={...currentRoom,body:f.elements.body.value,version:(currentRoom?.version||0)+1,updatedAt:new Date().toISOString()};}else await api.call('room.save',{body:f.elements.body.value,expectedVersion:draft?.version??currentRoom?.version??0});roomDrafts.delete(currentUser.id);if(mode==='live')await loadContext();render();toast(mode==='demo'?'Example notes updated — not saved':'Room notes saved');}catch(err){f.querySelector('.form-error').textContent=err.message+' Your draft is still here.';b.disabled=false;}};}}
function mustConnect(){if(mode==='offline'){formConnection();return true;}return false;}
function formConnection(){if(mode==='live'){view='connect';location.hash='connect';render();return;}clearSession();authPage='login';render();}
function newTask(){if(mustConnect())return;if(!canCreateTask())throw new Error('Ask the manager to create a task.');formDialog('Create a task','Keep the scope small enough to finish and review.',field('Task title','title')+field('Scope and instructions','description','','textarea')+field('Done when','acceptance','','textarea','List the observable results and tests required.')+select('Priority','priority',[['normal','Normal'],['high','High'],['low','Low']],'normal')+(isManager()?assigneePicker(): '')+`<label class="field"><span class="field-label">Prerequisites</span><div class="checkbox-list">${activeTasks(state).map(t=>`<label class="check-row"><input type="checkbox" name="dependencies" value="${h(t.id)}">${h(t.title)}</label>`).join('')||'<span class="checkbox-caption">No other tasks yet.</span>'}</div></label>`,'Create task',async d=>{if(!isManager())delete d.agentIds;await mutate('task.add',d);toast('Task created');});}
function newAgent(){if(mustConnect())return;if(!isManager())throw new Error('Only the manager can add workers.');if(mode==='live'){workerCreate();return;}formDialog('Add an agent','Give the role a name that can stay across sessions.',field('Agent name','name')+select('Role','role',[['Coordinator','Coordinator'],['Builder','Builder'],['Reviewer','Reviewer'],['Tester','Tester'],['Artist','Artist'],['Researcher','Researcher']])+field('Model or chat type','model','','text','For example: Sol 6.1, Astra, or regular ChatGPT.')+field('Capabilities and focus','capabilities','','textarea'),'Add agent',async d=>{await mutate('agent.add',d);toast('Agent added. Start a session when ready.');});}
function requireTaskManager(){if(!taskControlsReady())throw new Error('Task controls are waiting for the matching backend update.');if(!isManager()||!['live','demo'].includes(mode))throw new Error('Manager access required.');}
function assigneePicker(task){
  const rows=state.agents.filter(a=>a.enabled&&a.session||task&&assignedTo(task,a.id));
  return `<fieldset class="field task-assignees"><legend class="field-label">Agents assigned to this task</legend><p class="subtitle">Choose one or more agents. Each can save progress; an independent agent or the manager reviews their work.</p><div class="checkbox-list">${rows.map(a=>`<label class="check-row"><input type="checkbox" name="agentIds" value="${h(a.id)}" ${task&&assignedTo(task,a.id)?'checked':''}><span>${h(a.name)}${!a.enabled||!a.session?' (needs an active session)':''}</span></label>`).join('')||'<span class="checkbox-caption">A worker must sign in before receiving an assignment.</span>'}</div></fieldset>`;
}
function manageTaskAgents(id){requireTaskManager();const t=state.tasks.find(t=>t.id===id);if(!t||t.deletedAt)return;formDialog('Manage task agents',t.title,assigneePicker(t)+'<p class="instruction">Uncheck an agent to remove them. Clearing every agent returns the task to Ready and keeps its saved progress. Make sure removed agents have stopped working.</p>','Save agents',async d=>{await mutate('task.assign',{taskId:id,agentIds:d.agentIds,expectedVersion:taskVersion(t)});toast('Task agents saved');});}
function editTask(id){requireTaskManager();const t=state.tasks.find(t=>t.id===id);if(!t||t.deletedAt)return;formDialog('Edit task','Update the scope without changing saved progress or assignments.',field('Task title','title',t.title)+field('Scope and instructions','description',t.description,'textarea')+field('Done when','acceptance',t.acceptance,'textarea')+select('Priority','priority',[['normal','Normal'],['high','High'],['low','Low']],t.priority),'Save task',async d=>{await mutate('task.edit',{taskId:id,title:d.title,description:d.description,acceptance:d.acceptance,priority:d.priority,expectedVersion:taskVersion(t)});toast('Task saved');});}
function deleteTask(id){requireTaskManager();const t=state.tasks.find(t=>t.id===id);if(!t||t.deletedAt)return;const dependents=activeTasks(state).filter(x=>x.status!=='done'&&x.dependencies.includes(id));formDialog('Delete this task?',t.title,`<p class="instruction">This removes the task from the board and agent assignments. Its saved progress, agents and conversation are kept. You can restore it from Deleted tasks.</p>${dependents.length?`<div class="callout">Unfinished tasks depend on this task: ${dependents.map(x=>h(x.title)).join(', ')}. Finish or delete those tasks first.</div>`:''}`,'Delete task',async()=>{await mutate('task.delete',{taskId:id,expectedVersion:taskVersion(t)});toast('Task deleted. Restore it from Deleted tasks.');});$('#dialog-form [type="submit"]').classList.add('danger-solid');}
function deletedTasks(){requireTaskManager();const rows=state.tasks.filter(t=>t.deletedAt);formDialog('Deleted tasks','Saved task history stays here until you restore it.',`<div class="deleted-task-list">${rows.map(t=>`<div class="deleted-task-row"><div><strong>${h(t.title)}</strong><p class="subtitle">${h(taskNames(t))} · Deleted ${h(relative(t.deletedAt))}</p></div>${button('View task','task',t.id,'small')}${button('Restore','task-restore',t.id,'small')}</div>`).join('')||'<p class="instruction">No deleted tasks.</p>'}</div>`,'Close',async()=>{});}
function deletedTaskDetail(t){if(!isManager())return;formDialog(t.title,'Deleted task',`<div class="details"><strong>Agents</strong><p>${h(taskNames(t))}</p><strong>Scope</strong><p>${h(t.description)}</p><strong>Done when</strong><p>${h(t.acceptance)}</p><strong>Last checkpoint</strong><p>${h(t.checkpoint||'None')}</p><strong>Evidence</strong><p>${h(t.evidence||'None')}</p><strong>Conversation</strong>${state.messages.filter(m=>m.taskId===t.id).map(messageMarkup).join('')||'<p>No messages.</p>'}</div>${button('Restore task','task-restore',t.id)}`,'Close',async()=>{});}
function restoreTask(id){requireTaskManager();const t=state.tasks.find(t=>t.id===id);if(!t?.deletedAt)return;formDialog('Restore this task?',t.title,'<p class="instruction">Return this task to the board with its saved status, progress, conversation and remaining agents.</p>','Restore task',async()=>{await mutate('task.restore',{taskId:id,expectedVersion:taskVersion(t)});toast('Task restored');});}
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;if(!taskControlsReady()){formDialog(t.title,'Task controls are waiting for the matching backend update.',`<p class="instruction">${h(t.description||'')}<br>${h(t.checkpoint||'')}</p>`,'Close',async()=>{});return;}if(t.deletedAt){deletedTaskDetail(t);return;}const own=assignedTo(t,actor.id),editable=isManager()||own,reviewable=t.status==='review'&&(isManager()||!own);const info=`<div class="pill-line">${badge(t.status)}<span class="badge">${h(taskNames(t))}</span><span class="badge">${h(t.priority)} priority</span></div><div class="details"><strong>Scope</strong><p>${h(t.description||'No additional instructions.')}</p><strong>Done when</strong><p>${h(t.acceptance)}</p>${t.dependencies.length?`<strong>Prerequisites</strong><p>${t.dependencies.map(d=>h(state.tasks.find(x=>x.id===d)?.title||d)).join('<br>')}</p>`:''}${t.checkpoint?`<strong>Latest checkpoint</strong><p>${h(t.checkpoint)}</p>`:''}${t.evidence?`<strong>Evidence</strong><p>${h(t.evidence)}</p>`:''}${t.review?`<strong>Review</strong><p>${h(t.review)}</p>`:''}</div>`;let extra='',submit='Close';if(t.status==='ready'){extra=isManager()?assigneePicker(t):'<p class="instruction">Claim this assignment under your worker name.</p>';submit=isManager()?'Assign task':'Claim task';}else if(reviewable){extra=select('Review outcome','outcome',[['approve','Approve'],['changes','Request changes']])+field('Review results','review','','textarea');submit='Save review';}else if(t.status!=='done'&&t.status!=='review'&&editable){extra=select('Status','status',[['working','In progress'],['blocked','Blocked'],['review','Submit for review']],t.status)+field('Progress and next steps','checkpoint',t.checkpoint,'textarea')+field('Evidence and test results','evidence',t.evidence,'textarea');submit='Save update';}else if(t.status==='review'&&own){extra='<div class="callout">Your work is awaiting an independent review from the manager or another worker.</div>';}
const conversation=state.messages.filter(m=>m.taskId===id);extra+=`<div class="split-label"><span class="field-label">Task conversation</span><button type="button" class="text-button" data-action="task-message" data-id="${h(id)}">Add message</button></div>${conversation.slice(-4).map(messageMarkup).join('')||'<p class="subtitle">No messages yet.</p>'}`;if(isManager()&&taskAssignees(t).length&&t.status!=='done')extra+=`<div class="spacer"></div><button type="button" class="text-button" data-action="release" data-id="${h(id)}">Release task for reassignment</button>`;if(isManager())extra+=`<div class="task-management actions">${button('Edit task','task-edit',id)}${t.status!=='done'?button('Manage agents','task-agents',id):''}${button('Delete task','task-delete',id,'danger')}</div>`;formDialog(t.title,'Task '+t.id.slice(0,8),info+extra,submit,async d=>{if(t.status==='ready'){if(isManager()){if(!d.agentIds.length)throw new Error('Select at least one agent.');await mutate('task.assign',{taskId:id,agentIds:d.agentIds,expectedVersion:taskVersion(t)});}else await mutate('task.claim',{taskId:id,agentId:actor.id,expectedVersion:taskVersion(t)});}else if(reviewable){await mutate('task.review',{taskId:id,expectedVersion:taskVersion(t),approve:d.outcome==='approve',review:d.review});}else if(editable&&t.status!=='review'&&t.status!=='done'){await mutate('task.progress',{taskId:id,...d,expectedVersion:taskVersion(t)});}else return;toast('Task saved');});}
function project(){if(mustConnect())return;if(!isManager())throw new Error('Only the manager can edit project direction.');formDialog('Project direction','Every handoff includes these shared goals and rules.',field('Project name','name',state.project.name)+field('Current milestone','goal',state.project.goal,'textarea')+field('Game repository URL','gameRepo',state.project.gameRepo,'url')+field('Project rules','rules',state.project.rules,'textarea'),'Save direction',async d=>{await mutate('project.update',d);});}
function note(id){if(mustConnect())return;if(!isManager())throw new Error('Only the manager can edit shared notes.');const n=state.memory.find(n=>n.id===id);formDialog(n?'Edit project note':'Add project note','Record an agreed decision or a reusable reference.',field('Title','title',n?.title)+field('Note','body',n?.body,'textarea'),'Save note',async d=>{await mutate('memory.save',{...d,memoryId:n?.id,expectedUpdatedAt:n?.updatedAt});});}
function newBuild(){if(mustConnect())return;formDialog('Add playable build','Keep evidence linked to the version you actually tested.',field('Build name','title')+field('Playable or release URL','url','','url')+field('Commit or version','commit')+field('What changed / known issues','notes','','textarea')+field('Tests performed and results','tests','','textarea'),'Save build',async d=>{await mutate('build.add',d);});}
function newRequest(){if(mustConnect())return;formDialog('Ask the manager','Explain what decision would unblock this work.',field('Question','title')+field('Context and options','body','','textarea')+select('Related task','taskId',[['','No task'],...activeTasks(state).map(t=>[t.id,t.title])]),'Save question',async d=>{await mutate('request.add',d);});}
function resolve(id){if(!isManager())throw new Error('Only the manager can answer requests.');const r=state.requests.find(r=>r.id===id);formDialog('Answer the team',r.title,`<div class="details"><p>${h(r.body)}</p></div>`+field('Your decision','answer','','textarea'),'Save answer',async d=>{await mutate('request.resolve',{requestId:id,answer:d.answer});});}
function startSession(id){const a=agent(id);formDialog(a.session?'Replace this session?':'Start agent session',a.name,`<p class="instruction">${a.session?'This will invalidate the previous session and transfer its unfinished assignments. Make sure the old chat has stopped.':'This creates a session identity for this agent and prepares its first handoff.'}</p><div class="callout">The session ID identifies a run. It is not a password and does not grant GitHub access.</div>`,'Create session and handoff',async()=>{await mutate('agent.session',{agentId:id});showText(a.name+' · handoff',handoff(state,id,store?.repo));return true;});}
function exportBoard(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`relay-${mode==='demo'?'example-':''}backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(mode==='demo'?'Example board exported':'Board backup exported');}
function demo(){hardwareUI.reset();updates.reset();dm.reset();demoDM.reset();recoverySecret='';store?.disconnect();store=null;roomDrafts.clear();messageDrafts.clear();currentUser=null;workspaceManager=null;backendCapabilities={};currentRoom=null;workers=[];actor={id:'owner',owner:true};mode='demo';state=emptyState('Medieval Game Studio');const now=Date.now();let seq=0;const add=(type,payload,act=actor)=>{const id='example-'+(++seq);state=applyOperation(state,{id,type,payload},act,new Date(now-(24-seq)*120000).toISOString());return id;};add('project.update',{name:'Medieval Game Studio',goal:'Bring the next battle to life. Movement, combat and a build worth playing.',rules:'Keep the game playable. Save checkpoints. Review before merging.',gameRepo:''});const forge=add('agent.add',{name:'Forge',role:'Builder',model:'Sol 6.1'}),scout=add('agent.add',{name:'Scout',role:'Tester',model:'Sol 6.1'}),atlas=add('agent.add',{name:'Atlas',role:'Coordinator',model:'Astra'});[forge,scout,atlas].forEach(agentId=>add('agent.session',{agentId}));let t=add('task.add',{title:'Smooth cavalry turning around buildings',description:'Improve steering without changing unit speed.',acceptance:'Cavalry navigate tight corners without clipping.',priority:'high'});add('task.claim',{taskId:t,agentId:forge});add('task.progress',{taskId:t,status:'working',checkpoint:'Steering adjustments drafted. Next: check dense formations.',evidence:''});t=add('task.add',{title:'Check spearmen against charging cavalry',description:'Compare equal-cost formations.',acceptance:'Record three repeatable battle outcomes.',priority:'normal'});add('task.claim',{taskId:t,agentId:scout});add('task.progress',{taskId:t,status:'review',checkpoint:'Example test report ready for review.',evidence:'Example only: three battle scenarios recorded.'});add('task.add',{title:'Improve village building placement',description:'Make hamlets readable at campaign scale.',acceptance:'Buildings remain distinct when zoomed out.',priority:'normal'});add('task.add',{title:'Add a clear post-battle summary',description:'Show losses and rewards.',acceptance:'Summary agrees with battle results.',priority:'low'});add('request.add',{title:'How strong should a cavalry charge feel?',body:'Choose the intended advantage against unsupported archers before we tune the next pass.',taskId:''});add('memory.save',{title:'Current design direction',body:'Example project: readable battles, strong unit identities and a campaign map that stays responsive.'});add('message.add',{body:'Movement is the next milestone. Keep changes focused and leave testable handoffs.'});view='overview';location.hash='overview';render();}
const passwordField=(label,key,autocomplete='new-password')=>`<label class="field"><span class="field-label">${h(label)}</span><input name="${key}" aria-label="${h(label)}" type="password" required minlength="12" maxlength="256" autocomplete="${autocomplete}" placeholder="${autocomplete==='new-password'?'At least 12 characters':''}"></label>`;
const loginField=(value='')=>`<label class="field"><span class="field-label">Username</span><input name="username" aria-label="Username" required maxlength="60" autocomplete="username" autocapitalize="none" spellcheck="false" value="${h(value)}" placeholder="Your login name"></label>`;
function renderAuth(){const unavailable=!api.configured||authStatus?.deleted||authError,setup=authPage==='setup',recover=authPage==='recovery';document.title=(setup?'Create manager':recover?'Reset manager password':'Sign in')+' · Relay';$('#auth-screen').innerHTML=`<div class="auth-layout"><div class="auth-story"><a href="#" class="brand"><span class="brand-mark">r</span><span>relay<span class="brand-sub">YOUR AGENT STUDIO</span></span></a><div class="auth-story-main"><div class="eyebrow">ONE TEAM. A ROOM FOR EVERY AGENT.</div><h1>Pick up where<br>you left off.</h1><p>A shared home for your game, your ideas and the chats helping you build it.</p><div class="room-preview"><div class="room-preview-top"><span class="avatar">F</span><div><strong>Welcome, Forge.</strong><small>Your room · Your next step</small></div><span class="preview-dot"></span></div><div class="preview-task"><span class="task-indicator working"></span><span>Build the next playable milestone</span></div><div class="preview-task"><span class="task-indicator"></span><span>Leave a clear handoff for tomorrow</span></div><div class="preview-label">AN EXAMPLE WORKER ROOM</div></div></div><p class="auth-story-foot">The same project, across every new session.</p></div><div class="auth-main"><div class="auth-card"><div class="eyebrow">CODERCODE STUDIO</div><h2>${setup?'Your studio starts here.':recover?'Get back to your studio.':'Welcome to Relay.'}</h2><p class="auth-intro">${setup?'Create the one manager account. You’ll invite workers after signing in.':recover?'Use your saved recovery code to reset the manager password.':'Choose your role and sign in to your own space.'}</p>${!setup&&!recover?`<div class="role-tabs" role="group" aria-label="Sign-in role"><button type="button" data-action="auth-role" data-id="manager" aria-pressed="${authRole==='manager'}" class="${authRole==='manager'?'active':''}">${icon('connect')}<strong>Manager</strong><span>Run your studio</span></button><button type="button" data-action="auth-role" data-id="worker" aria-pressed="${authRole==='worker'}" class="${authRole==='worker'?'active':''}">${icon('team')}<strong>Worker</strong><span>Open your room</span></button></div>`:''}${!api.configured?'<div class="activation-note"><strong>Sign-in is waiting for activation</strong><p>The private account service needs to be connected before real passwords can be used. You can explore the example board now.</p></div>':authStatus?.deleted?'<div class="activation-note"><strong>This studio has been deleted</strong><p>Account access and project data have been removed from the app.</p></div>':authError?`<div class="form-error">${h(authError)} ${button('Try again','auth-retry','','small')}</div>`:''}<form id="auth-form"><fieldset ${unavailable||authBusy?'disabled':''}>${setup?field('Your name','name')+loginField()+field('Private setup code','setupCode','','password','Use the private code provided when the account service was activated.'):loginField()}${recover?field('Recovery code','recoveryCode','','password')+passwordField('New password','password')+passwordField('Confirm new password','confirm'):passwordField(setup?'Choose a password':'Password','password',setup?'new-password':'current-password')+(setup?passwordField('Confirm password','confirm'):'')}<div class="form-error" role="alert" id="auth-form-error"></div><button type="submit" class="button primary auth-submit">${authBusy?'Please wait…':setup?'Create my manager account':recover?'Reset manager password':`Sign in as ${authRole}`}</button></fieldset></form><div class="auth-links">${setup||recover?button('Back to sign in','auth-login','','text-button'):authRole==='manager'?button('Reset password','auth-recovery','','text-button'):'<span>Forgot your password? Ask your manager to reset it.</span>'}${!setup&&!recover&&authStatus?.needsSetup&&!authStatus?.deleted?button('First time? Set up your manager account','auth-setup','','text-button'):''}</div><div class="auth-divider"><span>or take a look around</span></div><div class="auth-demo-actions">${button('Explore example board','demo','','auth-demo')}${button('Preview a worker room','demo-worker','','auth-demo')}</div><p class="auth-bottom">Each worker gets a separate login and room. The team’s tasks and messages stay together.</p></div></div></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f)),b=f.querySelector('[type="submit"]');b.disabled=true;$('#auth-form-error').textContent='';try{if(!api.configured)throw new Error('The private account service has not been activated yet.');if((setup||recover)&&d.password!==d.confirm)throw new Error('The passwords do not match.');if(setup){if(!d.name.trim()||!d.setupCode.trim())throw new Error('Enter your name and the private setup code.');const result=await api.setup({name:d.name.trim(),username:d.username.trim(),password:d.password,setupCode:d.setupCode.trim()});await finishLogin();if(result.recoveryCode)showRecovery(result.recoveryCode);}else if(recover){const result=await api.call('recovery.reset',{username:d.username.trim(),recoveryCode:d.recoveryCode.trim(),newPassword:d.password});authPage='login';render();toast('Password reset. Sign in with your new password.');if(result.recoveryCode)showRecovery(result.recoveryCode);}else{await api.login({role:authRole,username:d.username.trim(),password:d.password});await finishLogin();}}catch(err){if($('#auth-form-error'))$('#auth-form-error').textContent=err.message;else toast(err.message);b.disabled=false;}};}
async function finishLogin(){hardwareUI.reset();updates.reset();dm.reset();store=api;if(!await loadContext())throw new Error('The sign-in session changed. Please try again.');mode='live';authPage='login';view='room';location.hash='room';render();dm.poll();toast('Welcome, '+currentUser.name);}
async function checkAccountStatus(){authBusy=true;authError='';render();try{if(api.configured)authStatus=await api.status();}catch(err){authError='Unable to reach the account service. '+err.message;}finally{authBusy=false;render();}}
function requireManager(){if(!isManager()||mode!=='live')throw new Error('Sign in with your manager account first.');}
function workerCreate(){requireManager();formDialog('Add a worker','Give this chat its own login and a room in your studio.',field('Worker name','name')+loginField()+passwordField('Worker password','password')+passwordField('Confirm worker password','confirm')+select('Work role','workRole',[['Builder','Builder'],['Coordinator','Coordinator'],['Reviewer','Reviewer'],['Tester','Tester'],['Artist','Artist'],['Researcher','Researcher']])+field('Model or chat type','model','','text','For example: Sol 6.1, Astra, or ChatGPT.')+field('Capabilities and focus','capabilities','','textarea')+'<div class="callout">Give this worker its username and password privately. Passwords are not included in the copyable instructions.</div>','Create worker',async d=>{if(d.password!==d.confirm)throw new Error('The passwords do not match.');await accountCall('workers.create',{name:d.name.trim(),username:d.username.trim(),password:d.password,workRole:d.workRole,model:d.model,capabilities:d.capabilities});const w=workers.find(w=>w.username.toLowerCase()===d.username.toLowerCase().trim());toast('Worker created');if(w){workerInstructions(w);return true;}});}
function workerInstructions(w){showText(w.name+' · sign-in instructions',`Open ${location.origin}${location.pathname}\nChoose Worker.\nUsername: ${w.username}\nName: ${w.name}\nRole: ${w.workRole||'Worker'}\n\nUse the password supplied privately by the manager. Your landing page is your own room. Check Private inbox for unread messages, then read the shared project memory and your assignments. Check the inbox again at work checkpoints; notifications do not restart an inactive chat. Save checkpoints and report progress to the team. Do not put login details in project messages or notes.`);}
function workerEdit(id){requireManager();const w=workers.find(w=>w.id===id);if(!w)throw new Error('This worker no longer exists.');formDialog('Manage '+w.name,'Worker account · @'+w.username,field('Worker name','name',w.name)+select('Work role','workRole',[['Builder','Builder'],['Coordinator','Coordinator'],['Reviewer','Reviewer'],['Tester','Tester'],['Artist','Artist'],['Researcher','Researcher']],w.workRole)+select('Account access','enabled',[['true','Enabled — can sign in'],['false','Disabled — access revoked']],String(w.enabled))+`<div class="account-tools">${button('Copy sign-in instructions','worker-instructions',id)}${button('Reset password','worker-reset',id)}${button('Delete worker','worker-delete',id,'danger')}</div>`,'Save worker',async d=>{await accountCall('workers.update',{workerId:id,name:d.name.trim(),workRole:d.workRole,enabled:d.enabled==='true'});toast('Worker updated');});}
function workerReset(id){requireManager();const w=workers.find(w=>w.id===id);formDialog('Reset '+w.name+'’s password','Existing worker sessions will end. Share the new password privately.',passwordField('Your manager password','currentPassword','current-password')+passwordField('New worker password','newPassword')+passwordField('Confirm new worker password','confirm'),'Reset worker password',async d=>{if(d.newPassword!==d.confirm)throw new Error('The passwords do not match.');await accountCall('workers.reset',{workerId:id,currentPassword:d.currentPassword,newPassword:d.newPassword});toast('Worker password reset');});}
function workerDelete(id){requireManager();const w=workers.find(w=>w.id===id);formDialog('Delete '+w.name+'?','Remove this worker’s account and personal room.',`<div class="callout danger-callout">The worker loses access immediately. Its account, private room, and direct messages are deleted. Shared project history remains.</div><div class="spacer"></div>`+passwordField('Your manager password','currentPassword','current-password')+field('Type the username to confirm','confirmation','','text',h(w.username)),'Delete worker',async d=>{if(d.confirmation!==w.username)throw new Error('Type the exact username to confirm.');await accountCall('workers.delete',{workerId:id,currentPassword:d.currentPassword,confirmation:d.confirmation});toast('Worker deleted');});$('#dialog-form [type="submit"]').classList.add('danger-solid');}
async function workerRoom(id){requireManager();const w=workers.find(w=>w.id===id),result=await api.call('room.read',{accountId:id}),r=result.room||result;formDialog(w.name+'’s room','Visible only to this worker and the manager.',field('Room notes','body',r.body||'','textarea','Worker room notes are separate from shared project memory.'),'Save room notes',async d=>{await accountCall('room.save',{accountId:id,body:d.body,expectedVersion:r.version??0});toast('Worker room saved');});}
async function updateApprovalSettings(){
  requireManager();const settings=await updates.getPolicy();requireManager();
  formDialog('Update approval policy','Choose who can sign off. Only your manager account can change these settings.',
    select('Required sign-offs','approvalMode', [['one','One sign-off — any eligible account'],['manager','My sign-off only — manager'],['agents','Two sign-offs — distinct agents']],settings.mode)+
    `<label class="field approval-toggle"><span><input type="checkbox" name="allowSelfApproval" ${settings.allowSelfApproval?'checked':''}> Allow agents to sign off their own updates</span></label><p class="instruction">Each account counts once. You can use “Publish with my approval” in the Update room to override missing reviews or requested changes. Checks must pass and the source must still match.</p>`,
    'Save approval policy',async d=>{requireManager();await updates.savePolicy({mode:d.approvalMode,allowSelfApproval:d.allowSelfApproval==='on'});toast('Update approval policy saved');});
}
function changePassword(){requireManager();formDialog('Change your password','Use a unique password of at least 12 characters.',passwordField('Current manager password','currentPassword','current-password')+passwordField('New password','newPassword')+passwordField('Confirm new password','confirm'),'Change password',async d=>{if(d.newPassword!==d.confirm)throw new Error('The passwords do not match.');await api.call('password.change',{currentPassword:d.currentPassword,newPassword:d.newPassword});clearSession();toast('Password changed. Sign in again with your new password.');});}
function showRecovery(code){recoverySecret=code;$('#modal-content').innerHTML=`<div class="modal-header"><div><h2>Save your recovery code</h2><p>This code is shown only now. Keep it somewhere private, separate from your password.</p></div></div><div class="callout">You can use this code to reset your manager password. Anyone with it can recover the manager account.</div><label class="field section-space"><span class="field-label">Manager recovery code</span><textarea id="recovery-code" class="recovery-code" readonly>${h(code)}</textarea></label><div class="actions">${button('Copy code','recovery-copy')}${button('Download code','recovery-download')}</div><div class="modal-footer">${button('I saved my recovery code','recovery-close','','primary')}</div>`;openDialog();}
function rotateRecovery(){requireManager();formDialog('Replace recovery code','Your previous recovery code will stop working.',passwordField('Current manager password','currentPassword','current-password'),'Generate new code',async d=>{const result=await api.call('recovery.rotate',{currentPassword:d.currentPassword});showRecovery(result.recoveryCode);return true;});}
function deleteWorkspace(){requireManager();formDialog('Permanently delete this studio?','This action cannot be undone in Relay.',`<div class="callout danger-callout">This deletes every app account, worker room, task, message, question and project note. Everyone is signed out. It does not remove the public website files or copies in provider backups.</div><div class="spacer"></div>`+passwordField('Your manager password','currentPassword','current-password')+field('Type DELETE MY STUDIO to confirm','confirmation'),'Delete entire studio',async d=>{if(d.confirmation!=='DELETE MY STUDIO')throw new Error('Type DELETE MY STUDIO exactly to confirm.');await api.call('workspace.delete',{currentPassword:d.currentPassword,confirmation:d.confirmation});authStatus={needsSetup:false,deleted:true};clearSession();toast('Studio data and accounts deleted.');});$('#dialog-form [type="submit"]').classList.add('danger-solid');}
function checkpoint(){if(mode==='offline'||isManager())return;formDialog('Save your next step','A checkpoint helps your next session continue without guessing.',field('Progress and next steps','checkpoint',agent(actor.id)?.checkpoint||'','textarea'),'Save checkpoint',async d=>{await mutate('agent.checkpoint',{agentId:actor.id,checkpoint:d.checkpoint});toast('Checkpoint saved');});}
function downloadText(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function demoWorker(){demo();demoDM.reset();const a=state.agents.find(a=>a.name==='Forge');currentUser={id:a.id,agentId:a.id,name:a.name,username:'forge',role:'worker',enabled:true,workRole:a.role,model:a.model};actor={id:a.id,owner:false,session:a.session};currentRoom={accountId:a.id,body:'My next step: test cavalry steering in a dense village.\n\nKeep unit speed unchanged. Save a before-and-after clip, then ask Scout for an independent review.',version:1,updatedAt:new Date().toISOString()};view='room';location.hash='room';render();}
async function accountAction(action,id){switch(action){case'demo-worker':demoWorker();return true;case'auth-role':authRole=id==='worker'?'worker':'manager';authPage='login';render();return true;case'auth-login':authPage='login';render();return true;case'auth-setup':authPage='setup';render();return true;case'auth-recovery':authPage='recovery';authRole='manager';render();return true;case'auth-retry':await checkAccountStatus();return true;case'logout':try{await api.logout();}finally{clearSession();}toast('Signed out');return true;case'worker-edit':workerEdit(id);return true;case'worker-reset':workerReset(id);return true;case'worker-delete':workerDelete(id);return true;case'worker-room':await workerRoom(id);return true;case'worker-instructions':requireManager();workerInstructions(workers.find(w=>w.id===id));return true;case'update-policy':await updateApprovalSettings();return true;case'password-change':changePassword();return true;case'recovery-rotate':rotateRecovery();return true;case'workspace-delete':deleteWorkspace();return true;case'checkpoint':checkpoint();return true;case'recovery-copy':try{await navigator.clipboard.writeText(recoverySecret);toast('Recovery code copied');}catch{$('#recovery-code')?.select();toast('Select and copy the recovery code.');}return true;case'recovery-download':downloadText('Relay-manager-recovery-code.txt',`Relay manager recovery code\n\n${recoverySecret}\n\nKeep this private. Use Reset password on the manager login screen.\n`);return true;case'recovery-close':recoverySecret='';$('#modal').close();return true;default:return false;}}
async function initialize(){render();if(!api.configured)return;try{if(await api.restore()){store=api;await loadContext();mode='live';const route=location.hash.slice(1);view=Object.hasOwn(names,route)?route:'room';render();dm.poll();return;}}catch{api.disconnect();}await checkAccountStatus();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;try{if(await accountAction(action,id))return;switch(action){case'connect':formConnection();break;case'close':$('#modal').close();break;case'new-task':newTask();break;case'new-agent':newAgent();break;case'task':taskDetail(id);break;case'task-edit':editTask(id);break;case'task-agents':manageTaskAgents(id);break;case'task-delete':deleteTask(id);break;case'deleted-tasks':deletedTasks();break;case'task-restore':restoreTask(id);break;case'project':project();break;case'new-note':note();break;case'edit-note':note(id);break;case'new-build':newBuild();break;case'new-request':newRequest();break;case'resolve':resolve(id);break;case'session':if(!isManager())throw new Error('Manager access required.');startSession(id);break;case'handoff':if(!isManager()&&id!==actor.id)throw new Error('Open your own handoff from My room.');showText(name(id)+' · handoff',handoff(state,id,mode==='live'?'Relay accounts — '+location.origin:store?.repo));break;case'copy-text':await copyText($('#handoff-text').value);break;case'pause-agent':if(!isManager())throw new Error('Manager access required.');await mutate('agent.update',{agentId:id,enabled:!agent(id).enabled});toast('Agent updated');break;case'layout':taskLayout=id;render();break;case'channel':channel=id;render();break;case'refresh':if(mode==='live')await refresh();else toast('Sign in to refresh shared work');break;case'export':exportBoard();break;case'demo':demo();break;case'disconnect':clearSession();break;case'task-message':formDialog('Task message','This message stays with the assignment.',field('Message','body','','textarea'),'Post message',async d=>{await mutate('message.add',{body:d.body,taskId:id});});break;case'release':if(!isManager())throw new Error('Only the manager can release assignments.');const releasedTask=state.tasks.find(t=>t.id===id);formDialog('Release this task?','Make sure its current worker has stopped.','<p class="instruction">The saved checkpoint remains. Another agent will be able to claim this assignment.</p>','Release task',async()=>{await mutate('task.release',{taskId:id,expectedVersion:taskVersion(releasedTask)});});break;}}catch(err){toast(err.message);}});
$('#menu-toggle').onclick=()=>{const sidebar=$('.sidebar');sidebar.classList.toggle('open');syncNavigation();if(sidebar.classList.contains('open'))sidebar.querySelector('a,button')?.focus();};
$('#dm-notification').addEventListener('click',e=>{
  if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
  e.preventDefault();
  if(location.hash!=='#inbox'){location.hash='inbox';return;}
  const wasOpen=$('.sidebar').classList.contains('open'),changed=view!=='inbox';
  $('.sidebar').classList.remove('open');
  if(changed){view='inbox';render();}else syncNavigation();
  // A repeated Inbox tap must not rebuild the composer or discard its draft.
  if(changed||wasOpen)$('#content').focus();
});
document.addEventListener('click',e=>{
  const sidebar=$('.sidebar'),toggle=$('#menu-toggle');
  if(!(e.target instanceof Element)||!sidebar.classList.contains('open')||getComputedStyle(toggle).display==='none'||sidebar.contains(e.target)||$('#modal').open)return;
  // Dismiss from page space while keeping links, buttons, and form controls usable.
  if(e.target.closest('a,button,input,select,textarea,label,summary,[role="button"],[role="link"],[contenteditable]:not([contenteditable="false"]),[data-action]'))return;
  sidebar.classList.remove('open');syncNavigation({returnFocus:true});
});
window.addEventListener('resize',()=>syncNavigation());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('open')&&!$('#modal').open){e.preventDefault();$('.sidebar').classList.remove('open');syncNavigation({returnFocus:true});}});
window.addEventListener('hashchange',()=>{const fromSidebar=$('.sidebar').contains(document.activeElement);view=location.hash.slice(1)||'overview';$('.sidebar').classList.remove('open');render();if(fromSidebar)$('#content').focus();});
$('#nav').addEventListener('click',e=>{const toggle=e.target.closest('[data-nav-group]');if(toggle){const open=sidebarNavigation.toggle(toggle.dataset.navGroup);toggle.setAttribute('aria-expanded',String(open));document.getElementById(toggle.getAttribute('aria-controls')).hidden=!open;return;}const link=e.target.closest('a');if(link&&link.hash===location.hash){if(view!==link.hash.slice(1)){view=link.hash.slice(1);$('.sidebar').classList.remove('open');render();$('#content').focus();}else if($('.sidebar').classList.contains('open')){$('.sidebar').classList.remove('open');syncNavigation();$('#content').focus();}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
setInterval(()=>{if(!document.hidden&&!deferBackgroundRender())refresh(true);},60000);
setInterval(()=>{if(!document.hidden&&view==='updates')updates.poll();},30000);
setInterval(()=>{if(!document.hidden&&view==='hardware')hardwareUI.poll(true);},30000);
initialize();
